package tdz.view.theme

/**
 * The Hacker theme canvas background: a seamlessly-tileable, blurry green katakana "matrix rain"
 * glyph field (PNG, ~31KB), embedded as a data-URI so it works offline. Quantized to a small green
 * palette; the randomized glyph layout is baked in at generation time. [hackerMatrixBg] layers a
 * soft phosphor vignette over the tiled field (brighter glow up top, darker edges so cards pop).
 */
const val matrixGlyphTile =
    "data:image/png;base64,"

val hackerMatrixBg =
    "radial-gradient(125% 95% at 50% 0%, rgba(8,30,14,0.30) 0%, rgba(0,0,0,0.72) 58%, rgba(0,0,0,0.90) 100%), " +
    "url(\"$matrixGlyphTile\")"
